#include <stdio.h>

struct No { int valor; struct No *prox; };

int main(void) {
    struct No c = {7, NULL};
    struct No b = {4, &c};
    struct No a = {9, &b};
    int soma = 0;
    for (struct No *p = &a; p != NULL; p = p->prox) {
        soma += p->valor;
    }
    printf("%d\n", soma);
    return 0;
}

